"use client";

import { AnimatePresence, motion } from "motion/react";
import { useEffect, useRef, useState } from "react";

export function DrawerTailwind({ title = "Notifications" }) {
  const [open, setOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const panel = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    document.body.style.overflow = "hidden";
    panel.current?.querySelector<HTMLElement>("button,input")?.focus();
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    document.addEventListener("keydown", onKey);
    return () => {
      document.body.style.overflow = "";
      document.removeEventListener("keydown", onKey);
      trigger.current?.focus();
    };
  }, [open]);
  return (
    <>
      <button ref={trigger} onClick={() => setOpen(true)} aria-haspopup="dialog" aria-expanded={open} className="h-9 rounded-lg border border-zinc-800 bg-zinc-900 px-4 text-sm font-medium text-zinc-100 hover:bg-zinc-800">Open settings</button>
      <AnimatePresence>
        {open && (
          <div className="fixed inset-0 z-50">
            <motion.div className="absolute inset-0 bg-black/50 backdrop-blur-sm" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onPointerDown={() => setOpen(false)} />
            <motion.div ref={panel} role="dialog" aria-modal="true" aria-label={title} className="absolute inset-y-0 right-0 flex w-[380px] max-w-[calc(100vw-2.5rem)] flex-col gap-4 border-l border-zinc-800 bg-zinc-950 p-6 text-zinc-100" initial={{ x: "100%" }} animate={{ x: 0 }} exit={{ x: "100%" }} transition={{ type: "spring", stiffness: 380, damping: 38 }}>
              <h2 className="text-lg font-semibold">{title}</h2>
              <p className="text-sm text-zinc-400">Choose what you want to hear about.</p>
              <div className="flex-1" />
              <div className="flex justify-end gap-2">
                <button onClick={() => setOpen(false)} className="h-9 rounded-lg border border-zinc-800 px-4 text-sm">Cancel</button>
                <button onClick={() => setOpen(false)} className="h-9 rounded-lg bg-indigo-500 px-4 text-sm font-medium text-white">Save preferences</button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </>
  );
}
